use me60os_core::{pai60_lib::pai60_divide, spa::SPA};
use sentinel_cortex::memory::crystal_runtime::{CrystalRuntime, DTC_TICK_INTERVAL_NS};
use std::{error::Error, time::{Duration, Instant}};

fn host_drive() -> Result<SPA, Box<dyn Error>> {
    let stat = std::fs::read_to_string("/proc/stat")?;
    let mut fields = stat.lines().next().ok_or("missing cpu row")?.split_whitespace();
    fields.next();
    let user: i64 = fields.next().ok_or("missing user counter")?.parse()?;
    fields.next();
    let system: i64 = fields.next().ok_or("missing system counter")?.parse()?;
    let sample = (user + system).rem_euclid(60) + 20;
    Ok(pai60_divide(SPA::from_int(sample), 60).ok_or("PAI conversion failed")?)
}

fn stats(values: &mut [u128]) -> serde_json::Value {
    values.sort_unstable();
    if values.is_empty() { return serde_json::Value::Null; }
    serde_json::json!({
        "count": values.len(), "min_ns": values[0],
        "mean_ns": values.iter().sum::<u128>() / values.len() as u128,
        "p99_ns": values[(values.len() * 99 / 100).min(values.len() - 1)],
        "max_ns": values[values.len() - 1]
    })
}

fn main() -> Result<(), Box<dyn Error>> {
    let state_dir = std::env::var_os("SENTINEL_CRYSTAL_STATE_DIR").ok_or("isolated state directory required")?;
    if std::fs::read_dir(&state_dir)?.next().is_some() { return Err("state directory must be empty".into()); }
    const TICKS: u64 = 680;
    const NODES: usize = 2000;
    let mut runtime = CrystalRuntime::in_memory(NODES);
    let initial = runtime.status();
    if initial.shm_active || initial.fractal_seed_shm_active || initial.qhc_tick != 0 {
        return Err("runtime is not isolated and fresh".into());
    }
    let start = Instant::now();
    let mut next_tick = start + Duration::from_nanos(DTC_TICK_INTERVAL_NS);
    let mut next_step = start + Duration::from_millis(500);
    let mut expected_ns = u128::from(DTC_TICK_INTERVAL_NS);
    let mut lateness = Vec::with_capacity(TICKS as usize);
    let mut tick_cost = Vec::with_capacity(TICKS as usize);
    let mut step_cost = Vec::with_capacity(40);
    let mut corrections = Vec::with_capacity(10);
    let mut energy_samples = Vec::with_capacity(40);
    let mut final_tick_elapsed_ns = 0;
    let mut tick_count = 0_u64;
    while tick_count < TICKS {
        let now = Instant::now();
        let tick_due = now >= next_tick;
        if tick_due {
            lateness.push(now.duration_since(next_tick).as_nanos());
            let begin = Instant::now();
            let interval = runtime.tick_dtc()?;
            tick_cost.push(begin.elapsed().as_nanos());
            tick_count += 1;
            if tick_count.is_multiple_of(68) {
                let status = runtime.status();
                corrections.push(serde_json::json!({"tick":status.qhc_tick,"qhc_correction_ns":status.qhc_last_drift_correction_ns}));
            }
            if tick_count == TICKS {
                final_tick_elapsed_ns = now.duration_since(start).as_nanos();
            } else {
                expected_ns += u128::from(interval);
            }
            next_tick += Duration::from_nanos(interval);
        }
        if now >= next_step {
            let drive = host_drive()?;
            runtime.inject_observability_spa(0, drive);
            let begin = Instant::now();
            runtime.step()?;
            step_cost.push(begin.elapsed().as_nanos());
            let status = runtime.status();
            energy_samples.push(serde_json::json!({
                "tick":status.qhc_tick,"drive_raw":drive.to_raw(),
                "lane_a_energy_raw":status.lane_a_energy_raw,"lane_b_energy_raw":status.lane_b_energy_raw,
                "dual_lane_portal_open":runtime.dual_lane_portal_open()
            }));
            next_step = now + Duration::from_millis(500);
        }
        let deadline = next_tick.min(next_step);
        std::thread::sleep(deadline.saturating_duration_since(Instant::now()));
    }
    let final_status = runtime.status();
    if final_status.shm_active || final_status.fractal_seed_shm_active || final_status.shm_sync_count != 0
        || final_status.liquid_memory_sync_count != 0 || std::fs::read_dir(&state_dir)?.next().is_some() {
        return Err("unexpected shared memory or persistence".into());
    }
    println!("{}", serde_json::json!({
        "scenario":std::env::args().nth(1),"nodes_per_lane":NODES,"ticks":TICKS,
        "expected_final_tick_ns":expected_ns,"observed_final_tick_ns":final_tick_elapsed_ns,
        "final_tick_lateness_ns":final_tick_elapsed_ns.saturating_sub(expected_ns),
        "deadline_lateness":stats(&mut lateness),"tick_call_cost":stats(&mut tick_cost),
        "step_call_cost":stats(&mut step_cost),"correction_boundaries":corrections,
        "energy_samples":energy_samples,"final_status":final_status,
        "excluded":["production service","SHM transport","checkpoint writes","kernel events","scheduler tasks","RT isolation","history-off comparison"]
    }));
    Ok(())
}
